type UnissuedContracts = [
  Assert<Equal<keyof FindUnissuedInvoicesParams, "store_id" | "reason" | "limit" | "cursor">>,
  Assert<Equal<UnissuedInvoiceReason, "awaiting_outside_number" | "awaiting_receipts" | "counter_held" | "blocked">>,
  Assert<Equal<UnissuedInvoiceExplanation["type"], "ready" | "paused" | "awaiting_outside_number" | "blocked">>,
  Assert<Equal<Awaited<ReturnType<OrderApi["invoice"]["findUnissued"]>>["items"][number], UnissuedInvoice>>,
  Assert<Equal<Awaited<ReturnType<OrderApi["invoice"]["detachOutside"]>>, Invoice | null>>,
  Assert<Equal<keyof AttachOutsideInvoiceParams, "store_id" | "order_id" | "number" | "document">>
];
